    gif: "image/gif",
    svg: "image/svg+xml",
    ico: "image/x-icon",
    bmp: "image/bmp",
    tif: "image/tiff",
    tiff: "image/tiff",
    json: "application/json",
    html: "text/html",
    htm: "text/html",
    txt: "text/plain",
    md: "text/markdown",
    css: "text/css",
    js: "text/javascript",
    mjs: "text/javascript",
    xml: "application/xml",
    yaml: "application/yaml",
    yml: "application/yaml",
    pdf: "application/pdf",
    zip: "application/zip",
    wasm: "application/wasm",
